  "gemini": "data:image/png;base64,",
  "githubcopilot": "data:image/png;base64,",
  "grok": "data:image/png;base64,",
  "grokbot": "data:image/png;base64,",
  "groq": "data:image/png;base64,",
  "hermesagent": "data:image/png;base64,",
  "kimi": "data:image/png;base64,",
  "minimax": "data:image/png;base64,",
  "mistral": "data:image/png;base64,",
  "openai": "data:image/png;base64,",
  "openclaw": "data:image/png;base64,",
